//! The glossary: the words the scenes use, each in a sentence or two, with the scene
//! that shows it. Opened from the scene list (or with G).

pub struct Entry {
    pub term: &'static str,
    pub meaning: &'static str,
    /// The scene to see it in, if there is one.
    pub scene: Option<&'static str>,
}

const fn e(term: &'static str, meaning: &'static str, scene: &'static str) -> Entry {
    Entry { term, meaning, scene: if scene.is_empty() { None } else { Some(scene) } }
}

