#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_entry_points_at_a_scene_that_exists() {
        let scenes = crate::scenes::registry();
        for (_, entries) in SECTIONS {
            for entry in *entries {
                if let Some(id) = entry.scene {
                    assert!(scenes.iter().any(|d| d.id == id), "\"{}\" links to a scene that does not exist: {id}", entry.term);
                }
            }
        }
    }
}
